function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? null : Number(v); }

// FIX 2026-08-01 (Fehleranalyse A5): proposal_type/target_type/target_value/proposed_value/
// time_horizon kommen ab hier ausschliesslich aus der frisch geladenen DB-Zeile (voriger Node
// "DB: Proposal laden (fuer Freigabe)"), nie aus dem POST-Body - siehe "POST: Baue Load-Query".
const loaded = $json;
const ctx = $('POST: Baue Load-Query').item.json;
const action = ctx.action;
const reviewer = ctx.reviewer;
const id = (loaded && loaded.id !== undefined && loaded.id !== null) ? Number(loaded.id) : null;

// FIX 2026-08-02 (Fehleranalyse A10, mittel): Optimistic Locking ueber das
// bereits vorhandene, aber nie genutzte version-Feld. submittedVersion kommt
// aus dem versteckten Formularfeld (beim Laden der Liste eingebettet) und
// wird NUR als Konkurrenz-Token verglichen, nicht als Inhaltsquelle (A5
// bleibt vollstaendig in Kraft - die eigentlichen Werte kommen weiterhin aus
// "loaded", nie aus ctx/dem Body). Hat sich der Vorschlag seit dem Laden der
// Seite bereits geaendert (jemand anderes hat ihn zwischenzeitlich bearbeitet,
// version wurde dabei hochgezaehlt), greift dieselbe "kein passender Vorschlag"-
// Behandlung wie bei einem falschen Status.
const submittedVersion = ctx.submittedVersion;
const versionMismatch = submittedVersion !== null && submittedVersion !== undefined
  && loaded && loaded.version !== undefined && Number(submittedVersion) !== Number(loaded.version);

// CHAMPION/CHALLENGER 2026-08-20: Freigabe ist jetzt zweistufig statt direkt proposed->activated.
// 'approve' (proposed->approved) markiert einen Vorschlag nur als geprueft/gebilligt - schreibt
// noch NICHTS in eine Zieltabelle. Erst 'activate' (approved->activated) macht ihn produktiv
// wirksam. Das nutzt die im Schema seit sql/038 vorhandenen, bis jetzt ungenutzten Status
// approved/rejected. Bewusst kein automatischer Vergleichslauf beim Genehmigen (Nutzerentscheidung,
// siehe EXPERIMENT_PLATFORM_REVIEW.md Punkt 3) - das ist ein spaeterer Ausbau. 'activate' ist nur
// aus status='approved' erreichbar (nicht direkt aus 'proposed'), damit der Zwischenschritt nicht
// umgangen werden kann. 'reject' bleibt aus beiden Stufen moeglich, falls sich ein bereits
// genehmigter Vorschlag vor der Aktivierung doch noch als ungeeignet herausstellt.
//
// FIX 2026-08-26: 'reset' (rejected/activation_failed -> proposed) und 'delete' (alles ausser
// 'activated') ergaenzt - Anlass war eine versehentliche Batch-Ablehnung ueber die UI ohne
// jede Undo-Moeglichkeit. 'activated' bleibt bewusst von beidem ausgeschlossen: ein bereits
// produktiv wirksamer Vorschlag hat reale Seiteneffekte (scoring_weights/pipeline_config/etc.)
// die 'delete' nicht rueckgaengig macht, und 'reset' wuerde den Audit-Trail verfaelschen. Ein
// echtes "Aktivierung rueckgaengig machen" ist bewusst NICHT gebaut (Nutzerentscheidung) - dafuer
// braeuchte es je Vorschlagstyp eine eigene Rueckabwicklung des Ziel-Werts.
const requiredStatus = { approve: 'proposed', reject: null, activate: 'approved', reset: null, delete: null };
const statusOk = loaded && loaded.status !== undefined && (
  action === 'reject'
    ? (loaded.status === 'proposed' || loaded.status === 'approved')
    : action === 'reset'
    ? (loaded.status === 'rejected' || loaded.status === 'activation_failed')
    : action === 'delete'
    ? (loaded.status !== 'activated')
    : loaded.status === requiredStatus[action]
);

// FIX 2026-08-01 (Fehleranalyse A8, hoch; loest gleichzeitig A7 vollstaendig ab): zentrale
// Regeltabelle (Datentyp/Min/Max/NULL-Policy) je Vorschlagstyp, serverseitig durchgesetzt vor
// jedem Ziel-Update. Ersetzt die bisherige Einzel-Allowlist fuer threshold_adjustment (A7,
// teilweise) durch eine einheitliche Struktur, die auch fuer strategy_parameter_change und
// regime_restriction gilt. Die Wertebereiche fuer strategy_parameter_change stammen aus den
// tatsaechlichen Default-Seed-Werten in sql/036 (stop_atr_multiplier/target_atr_multiplier/
// horizon_days sind die einzigen drei dort verwendeten Schluessel je Strategie - vollstaendig
// enumerierbar, kein Freitext). fit_multiplier-Grenzen aus dem Tabellenkommentar von
// strategy_regime_matrix (sql/032: "0=vollstaendig blockiert, 1=volle Eignung"). weight_value-
// Grenzen uebernommen aus der bereits bestehenden, getesteten Validierung in Workflow 09 (F2-
// Fix, MIN_WEIGHT/MAX_WEIGHT). Bewusst NICHT umgesetzt: eine maximale Schrittweite gegenueber
// dem aktuellen Live-Wert (wuerde eine zusaetzliche Vorab-Query je Ziel erfordern) - die
// absoluten Grenzen unten schliessen aber bereits das im Fund konkret genannte Beispiel
// (MAX_RISK_PER_TRADE_PCT auf 99%) zuverlaessig aus.
const RULE_TABLE = {
  threshold_adjustment: {
    MIN_REWARD_RISK_RATIO:        { min: 0.5, max: 10,  allowNull: false },
    MAX_RISK_PER_TRADE_PCT:       { min: 0.1, max: 10,  allowNull: false },
    MAX_POSITION_VALUE_PCT:       { min: 1,   max: 100, allowNull: false },
    MAX_OPEN_POSITIONS:           { min: 1,   max: 50,  allowNull: false, integer: true },
    MAX_SECTOR_EXPOSURE_PCT:      { min: 1,   max: 100, allowNull: false },
    MAX_DIRECTIONAL_EXPOSURE_PCT: { min: 1,   max: 100, allowNull: false },
    MAX_PORTFOLIO_DRAWDOWN_PCT:   { min: 1,   max: 100, allowNull: false },
    DRY_RUN:                      { min: 0,   max: 1,   allowNull: false, integer: true },
    REQUIRE_CONFIRMATION:         { min: 0,   max: 1,   allowNull: false, integer: true }
  },
  strategy_parameter_change: {
    stop_atr_multiplier:   { min: 0.3, max: 5,  allowNull: false },
    target_atr_multiplier: { min: 0.5, max: 10, allowNull: false },
    horizon_days:           { min: 1,  max: 60, allowNull: false, integer: true }
  }
};
const FIT_MULTIPLIER_RULE = { min: 0, max: 1, allowNull: false };
const WEIGHT_VALUE_RULE = { min: 0.1, max: 3.0, allowNull: false };
const VALID_STRATEGIES = new Set(['mean_reversion', 'trend_following', 'breakout', 'news_event']);
const VALID_COMBINED_REGIMES = new Set(['bull_trend_low_vol', 'bull_trend_high_vol', 'sideways_low_vol', 'sideways_high_vol', 'bear_trend', 'stress', 'unknown']);

function checkRule(rule, value) {
  if (value === null) return rule.allowNull ? { ok: true } : { ok: false, reason: 'Wert fehlt/nicht numerisch' };
  if (rule.integer && !Number.isInteger(value)) return { ok: false, reason: 'Wert muss ganzzahlig sein' };
  if (value < rule.min || value > rule.max) return { ok: false, reason: `Wert ${value} ausserhalb des zulaessigen Bereichs [${rule.min}, ${rule.max}]` };
  return { ok: true };
}

// FIX 2026-08-22 (A2, Haertungsauftrag): native Postgres-Parameter ($1/$2/...) statt
// String-Interpolation (pgStr). id/reviewer/proposedValue/targetType/targetValue/etc. werden
// jetzt als echte, typisierte Werte gebunden statt in den SQL-Text eingebettet. Platzhalter
// werden ueber mehrere Statements im selben BEGIN/COMMIT-Block wiederverwendet (live per
// WF97-Sandbox vorab verifiziert, dass n8n/pg das unterstuetzt - siehe RSS-Quellen/Watchlist-
// Faelle vom selben Tag).
const eligibleFragment = "EXISTS (SELECT 1 FROM trading.learning_rule_proposals WHERE id = $1 AND status = 'approved')";

let sql;
let sqlParams = [];

if (id === null || !statusOk || versionMismatch) {
  // Kein passender, noch offener Vorschlag fuer diese Aktion gefunden (falscher
  // Status fuer die angeforderte Aktion, oder er wurde zwischenzeitlich veraendert,
  // siehe versionMismatch oben) - egal was action/id im Body behaupten.
  sql = 'SELECT 1;';
} else if (action === 'reject') {
  sql = `UPDATE trading.learning_rule_proposals
    SET status = 'rejected', reviewed_at = now(), reviewed_by = $2, version = version + 1
    WHERE id = $1 AND status IN ('proposed', 'approved');`;
  sqlParams = [id, reviewer];
} else if (action === 'approve') {
  // Nur Statuswechsel proposed->approved - keine Zieltabelle wird beruehrt. Die
  // eigentliche Wertepruefung (RULE_TABLE) und der produktive Schreibvorgang
  // passieren erst bei 'activate'.
  sql = `UPDATE trading.learning_rule_proposals
    SET status = 'approved', reviewed_at = now(), reviewed_by = $2, version = version + 1
    WHERE id = $1 AND status = 'proposed';`;
  sqlParams = [id, reviewer];
} else if (action === 'reset') {
  sql = `UPDATE trading.learning_rule_proposals
    SET status = 'proposed', reviewed_at = NULL, reviewed_by = NULL, version = version + 1
    WHERE id = $1 AND status IN ('rejected', 'activation_failed');`;
  sqlParams = [id];
} else if (action === 'delete') {
  sql = `DELETE FROM trading.learning_rule_proposals WHERE id = $1 AND status <> 'activated';`;
  sqlParams = [id];
} else if (action === 'activate') {
  const proposalType = String(loaded.proposal_type || 'weight_adjustment').trim();
  const targetType = String(loaded.target_type || '').trim();
  const targetValue = String(loaded.target_value || '').trim();
  const timeHorizon = String(loaded.time_horizon || '').trim();
  const proposedValue = pgNum(loaded.proposed_value);

  // Zentrale Pruefung: Zielobjekt (Allowlist) + Wertebereich, je Vorschlagstyp.
  let validationFailed = false;
  let validationReason = '';

  if (proposalType === 'threshold_adjustment') {
    const rule = RULE_TABLE.threshold_adjustment[targetType];
    if (!rule) { validationFailed = true; validationReason = 'Unbekannter config_key: ' + targetType; }
    else { const r = checkRule(rule, proposedValue); if (!r.ok) { validationFailed = true; validationReason = r.reason; } }
  } else if (proposalType === 'strategy_parameter_change') {
    if (!VALID_STRATEGIES.has(targetType)) { validationFailed = true; validationReason = 'Unbekannte Strategie: ' + targetType; }
    else {
      const rule = RULE_TABLE.strategy_parameter_change[targetValue];
      if (!rule) { validationFailed = true; validationReason = 'Unbekannter parameter_key: ' + targetValue; }
      else { const r = checkRule(rule, proposedValue); if (!r.ok) { validationFailed = true; validationReason = r.reason; } }
    }
  } else if (proposalType === 'regime_restriction') {
    if (!VALID_STRATEGIES.has(targetType)) { validationFailed = true; validationReason = 'Unbekannte Strategie: ' + targetType; }
    else if (!VALID_COMBINED_REGIMES.has(targetValue)) { validationFailed = true; validationReason = 'Unbekanntes combined_regime: ' + targetValue; }
    else { const r = checkRule(FIT_MULTIPLIER_RULE, proposedValue); if (!r.ok) { validationFailed = true; validationReason = r.reason; } }
  } else if (proposalType === 'strategy_deactivation') {
    if (!VALID_STRATEGIES.has(targetType)) { validationFailed = true; validationReason = 'Unbekannte Strategie: ' + targetType; }
  } else {
    // weight_adjustment (Default-Zweig) - kein fester Schluessel-Katalog (Quelle x Zeitfenster
    // sind frei kombinierbar, siehe Workflow 09), aber der Wertebereich wird durchgesetzt
    // (identische Grenzen wie die bereits getestete Validierung in Workflow 09, F2-Fix).
    const r = checkRule(WEIGHT_VALUE_RULE, proposedValue);
    if (!r.ok) { validationFailed = true; validationReason = r.reason; }
  }

  if (validationFailed) {
    sql = `UPDATE trading.learning_rule_proposals
      SET status = 'activation_failed', reviewed_at = now(), reviewed_by = $2, version = version + 1
      WHERE id = $1 AND status = 'approved';`;
    sqlParams = [id, reviewer];
  } else if (proposalType === 'threshold_adjustment') {
    sql = `WITH upd AS (
        UPDATE trading.pipeline_config SET value_numeric = $3, updated_at = now()
          WHERE config_key = $4 AND ${eligibleFragment}
          RETURNING 1
      )
      UPDATE trading.learning_rule_proposals
        SET status = CASE WHEN EXISTS(SELECT 1 FROM upd) THEN 'activated' ELSE 'activation_failed' END,
            reviewed_at = now(), reviewed_by = $2, version = version + 1,
            activated_at = CASE WHEN EXISTS(SELECT 1 FROM upd) THEN now() ELSE NULL END
        WHERE id = $1 AND status = 'approved';`;
    sqlParams = [id, reviewer, proposedValue, targetType];
  } else if (proposalType === 'strategy_parameter_change') {
    sql = `WITH upd AS (
        UPDATE trading.strategy_parameters SET parameter_value = $3, version = version + 1, source_proposal_id = $1, updated_at = now()
          WHERE strategy = $4 AND parameter_key = $5 AND ${eligibleFragment}
          RETURNING 1
      )
      UPDATE trading.learning_rule_proposals
        SET status = CASE WHEN EXISTS(SELECT 1 FROM upd) THEN 'activated' ELSE 'activation_failed' END,
            reviewed_at = now(), reviewed_by = $2, version = version + 1,
            activated_at = CASE WHEN EXISTS(SELECT 1 FROM upd) THEN now() ELSE NULL END
        WHERE id = $1 AND status = 'approved';`;
    sqlParams = [id, reviewer, proposedValue, targetType, targetValue];
  } else if (proposalType === 'regime_restriction') {
    // VERSIONIERUNG 2026-08-20 (sql/067, behebt Risiko 2 aus EXPERIMENT_PLATFORM_REVIEW.md):
    // statt in-place UPDATE (das rule_version unveraendert liess und dadurch alte Referenzen
    // auf 'regime-matrix-v1' stillschweigend andere Werte lesen liess) wird die alte Zeile
    // deaktiviert und eine neue, eigens benannte Version eingefuegt - exakt das gleiche Muster
    // wie beim scoring_weights-Zweig unten. rule_version bleibt als Audit-Label pro Zeile
    // erhalten; welche Zeile "aktuell" gilt, bestimmt jetzt active=TRUE (sql/067) statt des
    // Versionsstrings - WF06 und der Config-Snapshot in WF17 lesen entsprechend active=TRUE.
    const newRuleVersion = 'regime-matrix-v1-p' + id;
    const noteSuffix = ' [Lernvorschlag #' + id + ' aktiviert]';
    sql = `WITH deactivated AS (
        UPDATE trading.strategy_regime_matrix SET active = FALSE
          WHERE strategy = $4 AND combined_regime = $5 AND active = TRUE AND ${eligibleFragment}
          RETURNING notes
      ), inserted AS (
        INSERT INTO trading.strategy_regime_matrix (rule_version, strategy, combined_regime, fit_multiplier, blocked, active, notes)
        SELECT $6, $4, $5, $3, ($3 <= 0), TRUE,
               COALESCE((SELECT notes FROM deactivated), '') || $7
          WHERE EXISTS (SELECT 1 FROM deactivated)
        RETURNING 1
      )
      UPDATE trading.learning_rule_proposals
        SET status = CASE WHEN EXISTS(SELECT 1 FROM inserted) THEN 'activated' ELSE 'activation_failed' END,
            reviewed_at = now(), reviewed_by = $2, version = version + 1,
            activated_at = CASE WHEN EXISTS(SELECT 1 FROM inserted) THEN now() ELSE NULL END
        WHERE id = $1 AND status = 'approved';`;
    sqlParams = [id, reviewer, proposedValue, targetType, targetValue, newRuleVersion, noteSuffix];
  } else if (proposalType === 'strategy_deactivation') {
    const deactivatedReason = 'Lernvorschlag #' + id;
    sql = `WITH upd AS (
        UPDATE trading.strategy_status
          SET aktiv = FALSE, deactivated_at = now(), deactivated_reason = $3, source_proposal_id = $1, updated_at = now()
          WHERE strategy = $4 AND ${eligibleFragment}
          RETURNING 1
      )
      UPDATE trading.learning_rule_proposals
        SET status = CASE WHEN EXISTS(SELECT 1 FROM upd) THEN 'activated' ELSE 'activation_failed' END,
            reviewed_at = now(), reviewed_by = $2, version = version + 1,
            activated_at = CASE WHEN EXISTS(SELECT 1 FROM upd) THEN now() ELSE NULL END
        WHERE id = $1 AND status = 'approved';`;
    sqlParams = [id, reviewer, deactivatedReason, targetType];
  } else {
    const weightKey = [targetType, targetValue, timeHorizon].filter(Boolean).join(':');
    // FIX 2026-08-26: Postgres garantiert NICHT, dass mehrere Daten-CTEs im selben
      // Statement die Schreibeffekte der jeweils anderen sehen (alle lesen denselben
      // Schnappschuss von vor dem Statement) - die INSERT-CTE sah die alte aktive Zeile
      // trotz der deactivated-CTE noch als aktiv und crashte am Unique-Index
      // uq_scoring_weights_one_active_per_key. Fix: zwei getrennte Anweisungen statt
      // zwei CTEs im selben Statement - dank der BEGIN/COMMIT-Entfernung (selbes Fix-
      // Datum) laufen mehrere Anweisungen bereits sequenziell in einer impliziten
      // Transaktion und sehen sich dadurch korrekt gegenseitig.
      sql = `UPDATE trading.scoring_weights SET active = FALSE
        WHERE weight_key = $4 AND active = TRUE AND ${eligibleFragment};
      INSERT INTO trading.scoring_weights
        (weight_key, weight_value, version, active, source_proposal_id, activated_at, activated_by, metadata_json)
      SELECT $4, $3, COALESCE(MAX(version), 0) + 1, TRUE, $1, now(), $2, '{}'::jsonb
        FROM trading.scoring_weights
        WHERE weight_key = $4 AND ${eligibleFragment};
      UPDATE trading.learning_rule_proposals
        SET status = CASE WHEN EXISTS(SELECT 1 FROM trading.scoring_weights WHERE weight_key = $4 AND active = TRUE AND source_proposal_id = $1) THEN 'activated' ELSE 'activation_failed' END,
            reviewed_at = now(), reviewed_by = $2, version = version + 1,
            activated_at = CASE WHEN EXISTS(SELECT 1 FROM trading.scoring_weights WHERE weight_key = $4 AND active = TRUE AND source_proposal_id = $1) THEN now() ELSE NULL END
        WHERE id = $1 AND status = 'approved';`;
    sqlParams = [id, reviewer, proposedValue, weightKey];
  }
} else {
  sql = 'SELECT 1;';
}

return [{ json: { sql, sqlParams } }];

let __navHtml = null;
try { __navHtml = $('Nav laden (lernvorschlaege-WebhookGETAnsicht)').first().json.navHtml || $('Nav laden (lernvorschlaege-WebhookPOSTAenderung)').first().json.navHtml || null; } catch (e) { __navHtml = null; }

// FIX 2026-07-25: n8n-Plattform-Bug entdeckt - wenn eine Postgres-Abfrage 0 Zeilen liefert,
// wird der nachfolgende Node standardmaessig gar nicht ausgefuehrt, was die Webhook-Antwort
// crashen liess (leere Antwort, kein Fehler-Log, kein Execution-Eintrag - nur ueber Server-
// Logs als 'Task rejected by Runner: Offer expired' + interner n8n-TypeError sichtbar).
// Live reproduziert mit einer GARANTIERT leeren Abfrage auf einer bekannt funktionierenden
// Tabelle (trading.watchlist) - also kein Bug in dieser Tabelle/diesem Workflow, sondern ein
// generelles n8n-Verhalten. Fix: alwaysOutputData:true auf dem vorgelagerten Postgres-Node
// erzwingt ein (leeres) Platzhalter-Item, das hier herausgefiltert werden muss.
const rows = $input.all().map(i => i.json).filter(r => r && r.id !== undefined);

function esc(s) {
  return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function fmtDate(v) {
  if (!v) return '';
  return new Date(v).toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
}
function fmtNum(v) {
  return (v === null || v === undefined) ? '' : String(v);
}

const STATUS_LABEL = {
  proposed: 'wartet auf Pruefung',
  approved: 'genehmigt, wartet auf Aktivierung',
  activated: 'aktiviert',
  rejected: 'abgelehnt',
  activation_failed: 'Aktivierung fehlgeschlagen',
  expired: 'abgelaufen'
};
const STATUS_CLASS = {
  proposed: 'warn',
  approved: 'warn',
  activated: 'ok',
  rejected: 'danger',
  activation_failed: 'danger',
  expired: 'muted'
};

// Ergebnis-Hinweis nach einer POST-Aktion (Projekt-Muster: die Aktion rendert die Liste frisch,
// mit einem Streifen oben). Auf dem GET-Pfad hat "POST: Baue Load-Query" nie gelaufen -> $(...)
// wirft -> kein Streifen. Der Status in der Liste selbst ist die eigentliche Rueckmeldung -
// falls die Aktion wegen Versions-/Statuskonflikt ein No-op war, steht der Vorschlag unveraendert da.
let resultBanner = '';
try {
  const ctx = $('POST: Baue Load-Query').first().json;
  const A = { approve: 'genehmigt', reject: 'abgelehnt', reset: 'zurueckgesetzt', delete: 'geloescht', activate: 'aktiviert' };
  if (ctx && ctx.action) {
    const lbl = A[ctx.action] || ('Aktion "' + ctx.action + '"');
    resultBanner = '<div style="background:#1c3a24;border:1px solid #4caf50;color:#a5d6a7;border-radius:8px;padding:10px 16px;margin:0 0 16px;font-size:13px;">&#10003; Vorschlag ' + (ctx.id != null ? '#' + esc(ctx.id) + ' ' : '') + lbl + ' &mdash; sofern er im passenden Zustand war (sonst unveraendert, siehe Liste).</div>';
  }
} catch (e) { resultBanner = ''; }

const rowsHtml = rows.map(r => {
  const target = esc(r.target_type) + ': ' + esc(r.target_value) + (r.time_horizon ? ' @ ' + esc(r.time_horizon) : '');
  const change = fmtNum(r.current_value) + ' → <strong>' + fmtNum(r.proposed_value) + '</strong>';
  const metric = r.metric_name ? esc(r.metric_name) + ': ' + fmtNum(r.metric_value) : '';
  const badgeClass = STATUS_CLASS[r.status] || 'muted';
  const badgeLabel = STATUS_LABEL[r.status] || esc(r.status);
  const badge = '<span class="badge ' + badgeClass + '">' + esc(badgeLabel) + '</span>';

  // FIX 2026-08-26: 'delete' (fuer alles ausser 'activated') als eigenes, wiederverwendbares
  // Form+Button-Paar gebaut, weil es in mehreren Status-Zweigen unten angehaengt wird.
  // Confirm-Dialog serverseitig NICHT durchsetzbar (nur ein UI-Sicherheitsnetz) - der
  // eigentliche Schutz ist die status<>'activated'-Bedingung serverseitig in
  // "POST: Formular normalisieren + SQL bauen".
  const deleteId = 'fd-' + r.id;
  const deleteForm = '<form id="' + deleteId + '" method="POST" action="/webhook/lernvorschlaege" ' +
    'onsubmit="return confirm(\'Vorschlag #' + esc(r.id) + ' endgueltig loeschen?\');">' +
    '<input type="hidden" name="action" value="delete">' +
    '<input type="hidden" name="id" value="' + esc(r.id) + '">' +
    '<input type="hidden" name="version" value="' + esc(r.version) + '">' +
    '</form>';
  const deleteButton = '<button class="danger" form="' + deleteId + '" type="submit">Loeschen</button>';
  const canDelete = r.status !== 'activated';

  let actionCell;
  if (r.status === 'proposed' || r.status === 'approved') {
    const rejectId = 'fr-' + r.id;
    const rejectForm = '<form id="' + rejectId + '" method="POST" action="/webhook/lernvorschlaege">' +
      '<input type="hidden" name="action" value="reject">' +
      '<input type="hidden" name="id" value="' + esc(r.id) + '">' +
      // FIX 2026-08-02 (Fehleranalyse A10): version wird jetzt mitgeschickt,
      // damit der Server erkennen kann, ob sich der Vorschlag seit dem Laden
      // dieser Seite bereits geaendert hat (Optimistic Locking) - reines
      // Konkurrenz-Token, kein vertrauenswuerdiger Inhaltswert (die
      // eigentlichen Felder werden weiterhin serverseitig aus der DB
      // nachgeladen, siehe A5).
      '<input type="hidden" name="version" value="' + esc(r.version) + '">' +
      '<input type="hidden" name="reviewer" value="">' +
      '</form>';

    if (r.status === 'proposed') {
      const approveId = 'fa-' + r.id;
      actionCell = '<button form="' + approveId + '" type="submit">Genehmigen</button>' +
        '<button class="danger" form="' + rejectId + '" type="submit">Ablehnen</button>' +
        deleteButton +
        '<form id="' + approveId + '" method="POST" action="/webhook/lernvorschlaege">' +
        '<input type="hidden" name="action" value="approve">' +
        '<input type="hidden" name="id" value="' + esc(r.id) + '">' +
        '<input type="hidden" name="version" value="' + esc(r.version) + '">' +
        '</form>' +
        rejectForm + deleteForm;
    } else {
      const activateId = 'fx-' + r.id;
      actionCell = '<button form="' + activateId + '" type="submit">Aktivieren</button>' +
        '<button class="danger" form="' + rejectId + '" type="submit">Ablehnen</button>' +
        deleteButton +
        '<div class="hint-inline">genehmigt von ' + esc(r.reviewed_by || '') + (r.reviewed_at ? ' &middot; ' + fmtDate(r.reviewed_at) : '') + '</div>' +
        '<form id="' + activateId + '" method="POST" action="/webhook/lernvorschlaege">' +
        '<input type="hidden" name="action" value="activate">' +
        '<input type="hidden" name="id" value="' + esc(r.id) + '">' +
        '<input type="hidden" name="version" value="' + esc(r.version) + '">' +
        '</form>' +
        rejectForm + deleteForm;
    }
  } else if (r.status === 'rejected' || r.status === 'activation_failed') {
    // FIX 2026-08-26: "Zuruecksetzen" (zurueck auf 'proposed') ergaenzt - Anlass war eine
    // versehentliche Batch-Ablehnung ohne Undo-Moeglichkeit, siehe "POST: Formular
    // normalisieren + SQL bauen" fuer die serverseitige Absicherung (nur aus diesen beiden
    // Status erreichbar).
    const resetId = 'fz-' + r.id;
    const resetForm = '<form id="' + resetId + '" method="POST" action="/webhook/lernvorschlaege">' +
      '<input type="hidden" name="action" value="reset">' +
      '<input type="hidden" name="id" value="' + esc(r.id) + '">' +
      '<input type="hidden" name="version" value="' + esc(r.version) + '">' +
      '</form>';
    actionCell = '<button form="' + resetId + '" type="submit">Zuruecksetzen</button>' +
      deleteButton +
      '<div class="hint-inline">' + esc(r.reviewed_by || '') + (r.reviewed_at ? ' &middot; ' + fmtDate(r.reviewed_at) : '') + '</div>' +
      resetForm + deleteForm;
  } else {
    // activated / expired: kein Reset (Audit-Trail/reale Seiteneffekte bei 'activated'),
    // Loeschen bleibt fuer 'expired' weiterhin moeglich, fuer 'activated' nicht (canDelete).
    actionCell = esc(r.reviewed_by || '') + (r.activated_at ? ' · ' + fmtDate(r.activated_at) : (r.reviewed_at ? ' · ' + fmtDate(r.reviewed_at) : ''));
    if (canDelete) actionCell = deleteButton + '<br>' + actionCell + deleteForm;
  }

  return '<tr>' +
    '<td>' + esc(r.id) + '</td>' +
    '<td>' + target + '</td>' +
    '<td>' + change + '</td>' +
    '<td>' + esc(r.sample_size) + '</td>' +
    '<td>' + esc(r.confidence_level) + '<br><span class="hint-inline">' + metric + '</span></td>' +
    '<td class="reason">' + esc(String(r.reason || '').slice(0, 220)) + '</td>' +
    '<td>' + badge + '<br><span class="hint-inline">' + fmtDate(r.created_at) + '</span></td>' +
    '<td>' + actionCell + '</td>' +
    '</tr>';
}).join('\n');

const now = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
const pendingCount = rows.filter(r => r.status === 'proposed').length;
const approvedCount = rows.filter(r => r.status === 'approved').length;

const html = '<!DOCTYPE html>' +
