return [{ json: { html } }];

function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? null : Number(v); }

// FIX 2026-08-01 (Fehleranalyse A5): ab hier vertraut der Workflow dem Browser nur noch fuer
// id/action/reviewer/reason. Alle inhaltlichen Vorschlagsfelder (proposal_type/target_type/
// target_value/proposed_value/time_horizon) werden im naechsten Schritt frisch aus der DB
// geladen, nie aus dem POST-Body uebernommen - jedes versteckte Formularfeld mit einem
// abweichenden Wert wird dadurch wirkungslos.
const j = $json.body || $json;
const action = String(j.action || '').trim();
const id = pgNum(j.id);
const reviewer = String(j.reviewer || '').trim() || 'unbekannt';
const reason = String(j.reason || '').trim();
// FIX 2026-08-02 (Fehleranalyse A10): submittedVersion ist wie reviewer/reason
// ein zulaessiger Browser-Wert - kein Inhaltsfeld, sondern ein reines
// Konkurrenz-Token (Optimistic Locking), gegen den frisch geladenen
// DB-Wert geprueft in "POST: Formular normalisieren + SQL bauen".
const submittedVersion = pgNum(j.version);

// FIX 2026-08-22 (A2, Haertungsauftrag): native Postgres-Parameter statt String-Interpolation.
return {
  json: {
    action,
    reviewer,
    reason,
    id,
    submittedVersion,
    load_sql: id !== null
      ? `SELECT id, proposal_type, target_type, target_value, proposed_value, time_horizon, status, version
         FROM trading.learning_rule_proposals WHERE id = $1;`
      : `SELECT NULL::bigint AS id WHERE FALSE;`,
    load_sql_params: id !== null ? [id] : []
  }
};
